UPDATE rent_goal
   SET status = 'CONFIRMED',
       modified_date = NOW(),
       modified_nm = #{modifiedNm}
       , residence_months = #{months}
       , confirmed_listing_id = #{listingId}
 WHERE goal_id = #{goalId}
